-- PostgreSQL Database Schema for Scientific Document Manager
-- Compliant with PostgreSQL 14/15/16

-- 1. Users table
CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" VARCHAR(150) UNIQUE NOT NULL,
  "email" VARCHAR(255) UNIQUE NOT NULL,
  "password" VARCHAR(255) NOT NULL,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 2. Collections / Folders table (Hierarchical Tree View)
CREATE TABLE "collections" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" INTEGER NOT NULL,
  "parent_id" INTEGER NULL,
  "name" VARCHAR(255) NOT NULL,
  "color" VARCHAR(50),
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("parent_id") REFERENCES "collections" ("id") ON DELETE SET NULL
);

-- 3. Documents table
CREATE TABLE "documents" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" INTEGER NOT NULL,
  "primary_collection_id" INTEGER NULL,
  "title" VARCHAR(500) NOT NULL,
  "short_title" VARCHAR(255),
  "item_type" VARCHAR(100) DEFAULT 'journalArticle',
  "repository" VARCHAR(255),
  "archive_id" VARCHAR(100),
  "doi" VARCHAR(255),
  "url" VARCHAR(1000),
  "genre" VARCHAR(100),
  "date" TIMESTAMP WITH TIME ZONE,
  "language" VARCHAR(50),
  "license" VARCHAR(100),
  "version" VARCHAR(50),
  "citation_key" VARCHAR(100),
  "loc_in_archive" VARCHAR(255),
  "file_path" VARCHAR(1000),
  "file_size" BIGINT,
  "rag_status" VARCHAR(50) DEFAULT 'PENDING',
  "extra" TEXT,
  "date_added" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  "date_modified" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("primary_collection_id") REFERENCES "collections" ("id") ON DELETE SET NULL
);

-- 4. Document Collections (Many-to-Many grouping)
CREATE TABLE "document_collections" (
  "document_id" INTEGER NOT NULL,
  "collection_id" INTEGER NOT NULL,
  PRIMARY KEY ("document_id", "collection_id"),
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("collection_id") REFERENCES "collections" ("id") ON DELETE CASCADE
);

-- 5. Authors table
CREATE TABLE "authors" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "first_name" VARCHAR(150),
  "last_name" VARCHAR(150)
);

-- 6. Document Authors table (Ordered junction)
CREATE TABLE "document_authors" (
  "document_id" INTEGER NOT NULL,
  "author_id" INTEGER NOT NULL,
  "author_order" INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY ("document_id", "author_id"),
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("author_id") REFERENCES "authors" ("id") ON DELETE CASCADE
);

-- 7. Tags table
CREATE TABLE "tags" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" VARCHAR(100) UNIQUE NOT NULL
);

-- 8. Document Tags table
CREATE TABLE "document_tags" (
  "document_id" INTEGER NOT NULL,
  "tag_id" INTEGER NOT NULL,
  PRIMARY KEY ("document_id", "tag_id"),
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("tag_id") REFERENCES "tags" ("id") ON DELETE CASCADE
);

-- 9. Domains table
CREATE TABLE "domains" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" VARCHAR(150) UNIQUE NOT NULL
);

-- 10. Document Domains table
CREATE TABLE "document_domains" (
  "document_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  PRIMARY KEY ("document_id", "domain_id"),
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("domain_id") REFERENCES "domains" ("id") ON DELETE CASCADE
);

-- 11. Annotations table (PDF Direct Highlights & Sticky Notes)
CREATE TABLE "annotations" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" INTEGER NOT NULL,
  "user_id" INTEGER NOT NULL,
  "page_number" INTEGER NOT NULL,
  "type" VARCHAR(50) NOT NULL DEFAULT 'highlight', -- 'highlight', 'note', 'underline'
  "color" VARCHAR(50) DEFAULT '#ffeb3b',
  "rects" TEXT, -- JSON-stringified array of bounding box coordinates
  "selected_text" TEXT,
  "comment" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

-- 12. Personal Notes table
CREATE TABLE "notes" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "document_id" INTEGER NULL,
  "title" VARCHAR(255) NOT NULL,
  "content" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE
);

-- 13. Document Shares table (Google Drive-style Permissions: VIEW, COMMENT, EDIT)
CREATE TABLE "document_shares" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" INTEGER NOT NULL,
  "shared_with_user_id" INTEGER NOT NULL,
  "permission" VARCHAR(20) NOT NULL, -- 'VIEW', 'COMMENT', 'EDIT'
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "uq_document_user_share" UNIQUE ("document_id", "shared_with_user_id"),
  FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("shared_with_user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

-- 14. Collection Shares table (Folder Level Sharing, Inherited by contained docs)
CREATE TABLE "collection_shares" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "collection_id" INTEGER NOT NULL,
  "shared_with_user_id" INTEGER NOT NULL,
  "permission" VARCHAR(20) NOT NULL, -- 'VIEW', 'COMMENT', 'EDIT'
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "uq_collection_user_share" UNIQUE ("collection_id", "shared_with_user_id"),
  FOREIGN KEY ("collection_id") REFERENCES "collections" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("shared_with_user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

-- 15. Related Documents table (Manual & Inferred relationships)
CREATE TABLE "related_documents" (
  "document_id_1" INTEGER NOT NULL,
  "document_id_2" INTEGER NOT NULL,
  "relation_type" VARCHAR(50) DEFAULT 'manual',
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("document_id_1", "document_id_2"),
  FOREIGN KEY ("document_id_1") REFERENCES "documents" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("document_id_2") REFERENCES "documents" ("id") ON DELETE CASCADE
);

-- Indexing for performance
CREATE INDEX "idx_documents_owner" ON "documents" ("owner_id");
CREATE INDEX "idx_documents_primary_collection" ON "documents" ("primary_collection_id");
CREATE INDEX "idx_documents_doi" ON "documents" ("doi");
CREATE INDEX "idx_annotations_document_page" ON "annotations" ("document_id", "page_number");
CREATE INDEX "idx_notes_user_doc" ON "notes" ("user_id", "document_id");
